#include <bits/stdc++.h>
using namespace std;
int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);
 vector<vector<int>>P(n+2);for(int i=0;i<n;i++){int a;scanf("%d",&a);P[a].push_back(i);}
 // prev states: (minpos, best) ; "none" = (INF, bestAll)
 vector<pair<int,int>> prv; int prvNone=0; // prvNone = best total with v-1 having none kept
 for(int v=1;v<=n;v++){auto&p=P[v];int k=p.size();
  int bestAll=prvNone; for(auto&s:prv)bestAll=max(bestAll,s.second);
  vector<pair<int,int>> cur(k);
  // candidates: prev states with pos, value val + (#p < pos); none -> val + k
  vector<pair<int,int>> c; for(auto&s:prv){int cnt=lower_bound(p.begin(),p.end(),s.first)-p.begin();c.push_back({cnt,s.second+cnt});}
  c.push_back({k,prvNone+k});
  sort(c.begin(),c.end()); int m=c.size(); vector<int>suf(m+1,INT_MIN);
  for(int i=m-1;i>=0;i--)suf[i]=max(suf[i+1],c[i].second);
  int ptr=0;for(int j=0;j<k;j++){while(ptr<m&&c[ptr].first<=j)ptr++;cur[j]={p[j],suf[ptr]-j};}
  prv=cur;prvNone=bestAll;}
 int best=prvNone;for(auto&s:prv)best=max(best,s.second);printf("%d\n",n-best);}}

