int main(){int n,m;cin>>n>>m;vector<string>g(n);for(auto&s:g)cin>>s;
 int w=0;for(auto&s:g)for(char c:s)w+=c=='o';
 vector<long long>p2(w+1,1),f(w+2,0),G(w+2,0);for(int i=1;i<=w;i++)p2[i]=p2[i-1]*2%MOD;
 // f[j]: colorings of j cells where the red streak ending at j has even length>=2
 long long S=0;for(int j=2;j<=w;j++){if(j>2)S=(2*S+((j-1)%2==0))%MOD;f[j]=(S+(j%2==0))%MOD;}
 for(int j=2;j<=w;j++)G[j]=(G[j-1]+f[j]*p2[w-j])%MOD;
 long long ans=0;auto run=[&](int L){if(L>=2)ans=(ans+G[L])%MOD;};
 for(int i=0;i<n;i++){int L=0;for(int j=0;j<=m;j++){if(j<m&&g[i][j]=='o')L++;else{run(L);L=0;}}}
 for(int j=0;j<m;j++){int L=0;for(int i=0;i<=n;i++){if(i<n&&g[i][j]=='o')L++;else{run(L);L=0;}}}
 cout<<ans<<endl;}

