 for(int i=1;i<=n;i++){scanf("%d",&d[i]);if(d[i]==-1)neg=i;else sum+=d[i];}
 if(!neg&&sum%2){puts("-1");return 0;}
 for(int i=1;i<=n;i++)if(d[i]==-1)d[i]=0;
 if(neg&&sum%2)d[neg]=1;               // fix parity using one free vertex
