int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);vector<long long>a(n);long long s=0;
 for(auto&x:a){scanf("%lld",&x);s+=x;}
 if(s%n){puts("No");continue;}s/=n;
 long long net[40]={0},pos[40]={0},neg[40]={0};bool ok=true; // net[b]=#give 2^b - #receive 2^b
 for(auto x:a){long long d=x-s;if(d==0)continue;long long ad=llabs(d);
  if((ad&(ad-1))==0){int b=__builtin_ctzll(ad);if(d>0){pos[b]++;net[b]++;}else{neg[b]++;net[b]--;}continue;}
  long long lo=ad&-ad,hi=ad+lo; // ad = hi - lo
  if(hi&(hi-1)){ok=false;break;}int bh=__builtin_ctzll(hi),bl=__builtin_ctzll(lo);
  if(d>0){net[bh]++;net[bl]--;}else{net[bh]--;net[bl]++;}}
 for(int b=0;b<38&&ok;b++){long long x=net[b];if(x%2){ok=false;break;}
  if(x>0){if(pos[b]<x/2){ok=false;break;}net[b+1]+=x/2;}       // convert x/2 '+2^b' persons
  else if(x<0){if(neg[b]<-x/2){ok=false;break;}net[b+1]+=x/2;}}
 puts(ok?"Yes":"No");}}

