// can inserting one move along this axis shrink its range by 1?
bool canShrink(const vector<int>&p){int mx=*max_element(p.begin(),p.end()),mn=*min_element(p.begin(),p.end());
 if(mx-mn<2)return false;int fM=-1,lM=-1,fm=-1,lm=-1;
 for(int i=0;i<(int)p.size();i++){if(p[i]==mx){if(fM<0)fM=i;lM=i;}if(p[i]==mn){if(fm<0)fm=i;lm=i;}}
 return lM<fm||lm<fM;}
int main(){int T;cin>>T;while(T--){string s;cin>>s;vector<int>x={0},y={0};
 for(char c:s){x.push_back(x.back()+(c=='D')-(c=='A'));y.push_back(y.back()+(c=='W')-(c=='S'));}
 long long W=*max_element(x.begin(),x.end())-*min_element(x.begin(),x.end())+1;
 long long H=*max_element(y.begin(),y.end())-*min_element(y.begin(),y.end())+1;
 long long ans=W*H;if(canShrink(x))ans=min(ans,(W-1)*H);if(canShrink(y))ans=min(ans,W*(H-1));
 cout<<ans<<"\n";}}

