int main(){int t;scanf("%d",&t);while(t--){int n,m;scanf("%d %d",&n,&m);vector<long long>a(n+1);
 for(int i=1;i<=n;i++)scanf("%lld",&a[i]);vector<vector<int>>g(n+1),rg(n+1);
 for(int i=0;i<m;i++){int u,v;scanf("%d %d",&u,&v);g[u].push_back(v);rg[v].push_back(u);}
 // Kosaraju (iterative)
 vector<int>ord,comp(n+1,-1);vector<char>vis(n+1,0);
 for(int s=1;s<=n;s++){if(vis[s])continue;vector<pair<int,int>>st={{s,0}};vis[s]=1;
  while(!st.empty()){auto&[u,i]=st.back();if(i<(int)g[u].size()){int v=g[u][i++];if(!vis[v]){vis[v]=1;st.push_back({v,0});}}
   else{ord.push_back(u);st.pop_back();}}}
 int C=0;for(int k=n-1;k>=0;k--){int s=ord[k];if(comp[s]>=0)continue;vector<int>st={s};comp[s]=C;
  while(!st.empty()){int u=st.back();st.pop_back();for(int v:rg[u])if(comp[v]<0){comp[v]=C;st.push_back(v);}}C++;}
 // components are numbered in topological order (0 = source side)
 vector<long long>sz(C,0),sm(C,0);for(int i=1;i<=n;i++){sz[comp[i]]++;sm[comp[i]]+=a[i];}
 vector<vector<int>>cg(C);for(int u=1;u<=n;u++)for(int v:g[u])if(comp[u]!=comp[v])cg[comp[u]].push_back(comp[v]);
 vector<pair<long long,long long>>best(C); // (length, -?) longest path starting at comp: max len, min sum
 pair<long long,long long>ans={0,0};
 for(int c=C-1;c>=0;c--){long long L=0,S=0;for(int d:cg[c]){if(best[d].first>L||(best[d].first==L&&best[d].second<S)){L=best[d].first;S=best[d].second;}}
  best[c]={L+sz[c],S+sm[c]};
  if(best[c].first>ans.first||(best[c].first==ans.first&&best[c].second<ans.second))ans=best[c];}
 printf("%lld %lld\n",ans.first,ans.second);}}

