int main(){int t;scanf("%d",&t);while(t--){int n,q;scanf("%d %d",&n,&q);
 // P = sum M, PI = sum M*i, PJ = sum M*j (2D prefix sums)
 vector<vector<long long>>P(n+1,vector<long long>(n+1,0)),PI=P,PJ=P;
 for(int i=1;i<=n;i++)for(int j=1;j<=n;j++){long long x;scanf("%lld",&x);
  P[i][j]=x+P[i-1][j]+P[i][j-1]-P[i-1][j-1];PI[i][j]=x*i+PI[i-1][j]+PI[i][j-1]-PI[i-1][j-1];PJ[i][j]=x*j+PJ[i-1][j]+PJ[i][j-1]-PJ[i-1][j-1];}
 auto get=[&](vector<vector<long long>>&A,int a,int b,int c,int d){return A[c][d]-A[a-1][d]-A[c][b-1]+A[a-1][b-1];};
 string out;while(q--){int x1,y1,x2,y2;scanf("%d %d %d %d",&x1,&y1,&x2,&y2);long long w=y2-y1+1;
  long long S=get(P,x1,y1,x2,y2),SI=get(PI,x1,y1,x2,y2),SJ=get(PJ,x1,y1,x2,y2);
  long long r=w*(SI-x1*S)+(SJ-(long long)(y1-1)*S); // index = (i-x1)*w + (j-y1+1)
  out+=to_string(r);out+=' ';}
 puts(out.c_str());}}

