int main(){int t;cin>>t;while(t--){int n,A,B;string x;cin>>n>>A>>B>>x;memset(vis,0,sizeof vis);vis[0][0][0][0]=1;
 for(int i=0;i<n;i++){int d=x[i]-'0';for(int a=0;a<A;a++)for(int b=0;b<B;b++)for(int r=0;r<=i;r++)if(vis[i][a][b][r]){
