const long long MOD=998244353;
long long pw(long long b,long long e){long long r=1;b%=MOD;while(e){if(e&1)r=r*b%MOD;b=b*b%MOD;e>>=1;}return r;}
int main(){int n,m;scanf("%d %d",&n,&m);vector<vector<int>>d(n,vector<int>(m));
 for(auto&r:d)for(auto&x:r)scanf("%d",&x);
 long long fact=1;for(int i=1;i<=n;i++)fact=fact*i%MOD;long long inv=pw(fact,MOD-2),ans=0;
 for(int j=0;j<m;j++){vector<int>s(n);for(int i=0;i<n;i++)s[i]=d[i][j]-1; // city may only occupy the last d-1 turns
  sort(s.begin(),s.end());long long bad=1;for(int i=0;i<n;i++)bad=bad*max(0,s[i]-i)%MOD;
  ans=(ans+1-bad*inv%MOD+MOD)%MOD;}
 printf("%lld\n",ans);}

