int n,m;vector<vector<char>>lk;
bool fr(int x,int y){return x>=0&&y>=0&&x<n&&y<m&&!lk[x][y];}
// count free cells walking from (x,y) (inclusive) alternating moves a,b,a,b...
long long walk(int x,int y,int ax,int ay,int bx,int by){long long c=0;int t=0;
 while(fr(x,y)){c++;if(t%2==0){x+=ax;y+=ay;}else{x+=bx;y+=by;}t++;}return c;}
long long through(int x,int y){ // staircases containing free cell (x,y)
 long long f1=walk(x,y,0,1,1,0),b1=walk(x,y,-1,0,0,-1); // line: ... down, (cell), right, down ...
 long long f2=walk(x,y,1,0,0,1),b2=walk(x,y,0,-1,-1,0); // line: ... right, (cell), down, right ...
 return f1*b1+f2*b2-1;}
