// best[i] = max total health kept by a chain that ends exploding at i going outward one side
vector<ll> side(const vector<ll>&h){int n=h.size();vector<ll>L(n);vector<int>st;
 for(int i=0;i<n;i++){while(!st.empty()&&h[st.back()]-st.back()>h[i]-i)st.pop_back();
  ll j=st.empty()?-1:st.back();ll len=i-j;
  if(len>h[i]||j<0&&len>=h[i]){ll k=min<ll>(len,h[i]);L[i]=k*(2*h[i]-k+1)/2;} // chain dies out before j
  else L[i]=(j>=0?L[j]:0)+len*(2*h[i]-len+1)/2;
  st.push_back(i);}return L;}
int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);vector<ll>h(n);ll S=0;for(auto&x:h){scanf("%lld",&x);S+=x;}
 vector<ll>L=side(h);vector<ll>r(h.rbegin(),h.rend());vector<ll>R=side(r);reverse(R.begin(),R.end());
 ll ans=LLONG_MAX;for(int i=0;i<n;i++)ans=min(ans,S-(L[i]+R[i]-h[i])+h[i]);printf("%lld\n",ans);}}

