int dist_[202][202][B];short pr[202][202][B];
int main(){string s,t;cin>>s>>t;int n=s.size(),m=t.size();memset(dist_,-1,sizeof dist_);
 // BFS on (i,j,bal): adding a char advances each string whose next char matches
 queue<array<int,3>>q;dist_[0][0][0]=0;q.push({0,0,0});
 while(!q.empty()){auto[i,j,b]=q.front();q.pop();if(i==n&&j==m&&b==0)break;
  for(int c=0;c<2;c++){char ch=c?')':'(';int nb=b+(c?-1:1);if(nb<0||nb>=B)continue;
   int ni=i+(i<n&&s[i]==ch),nj=j+(j<m&&t[j]==ch);if(dist_[ni][nj][nb]>=0)continue;
   dist_[ni][nj][nb]=dist_[i][j][b]+1;pr[ni][nj][nb]=c;q.push({ni,nj,nb});}}
 // reconstruct backwards: find predecessor consistent with the stored char
 string res;int i=n,j=m,b=0;
 while(i||j||b){int c=pr[i][j][b];char ch=c?')':'(';int pb=b-(c?-1:1);bool found=false;
  for(int pi=max(0,i-1);pi<=i&&!found;pi++)for(int pj=max(0,j-1);pj<=j&&!found;pj++){
   if(dist_[pi][pj][pb]!=dist_[i][j][b]-1)continue;
   if(pi+(pi<n&&s[pi]==ch)!=i||pj+(pj<m&&t[pj]==ch)!=j)continue;
   res+=ch;i=pi;j=pj;b=pb;found=true;}}
