typedef long long ll;
pair<ll,ll> best;
void rec(ll m,ll cnt,ll used){ // greedy tower of remaining volume m
 if(m==0){best=max(best,make_pair(cnt,used));return;}
 ll a=cbrtl((long double)m);while((a+1)*(a+1)*(a+1)<=m)a++;while(a*a*a>m)a--;
 rec(m-a*a*a,cnt+1,used+a*a*a);                     // take the biggest cube a^3
 if(a>1)rec(a*a*a-1-(a-1)*(a-1)*(a-1),cnt+1,used+(a-1)*(a-1)*(a-1)); // take (a-1)^3, cap rest below a^3
}
