int main(){F[0]=1;for(int i=1;i<N;i++)F[i]=F[i-1]*i%MOD;IF[N-1]=pw(F[N-1],MOD-2);for(int i=N-1;i>0;i--)IF[i-1]=IF[i]*i%MOD;
