using namespace std;
// best right-down shot: T(x,y) = #targets with x'>=x, y'>=y, (x'-x)+(y'-y) <= k
int solve(const vector<string>&g,int k){int n=g.size(),m=g[0].size();
 vector<vector<int>>row(n,vector<int>(m+1,0)),D(n,vector<int>(m,0)),T(n+1,vector<int>(m,0));
 for(int i=0;i<n;i++)for(int j=0;j<m;j++)row[i][j+1]=row[i][j]+(g[i][j]=='#');
 for(int i=0;i<n;i++)for(int j=0;j<m;j++)D[i][j]=(g[i][j]=='#')+((i>0&&j+1<m)?D[i-1][j+1]:0); // prefix along anti-diagonal (rows <= i)
 auto diag=[&](int d,int lo,int hi)->int{ // cells (r, d-r) with lo<=r<=hi
  lo=max(lo,d-(m-1));hi=min(hi,n-1);hi=min(hi,d);if(lo>hi)return 0;
  int s=D[hi][d-hi];if(lo-1>=0&&d-(lo-1)<m)s-=D[lo-1][d-lo+1];return s;};
 int best=0;
 for(int x=n-1;x>=0;x--)for(int y=0;y<m;y++){
  int v=T[x+1][y]-diag(x+y+k+1,x+1,x+k+1)+(row[x][min(m,y+k+1)]-row[x][y]); // drop distance k+1 layer, add row x
  T[x][y]=v;best=max(best,v);}
 return best;}
int main(){int t;scanf("%d",&t);while(t--){int n,m,k;scanf("%d %d %d",&n,&m,&k);vector<string>g(n);static char buf[100005];
 for(auto&s:g){scanf("%s",buf);s=buf;}int ans=0;
 for(int f=0;f<4;f++){vector<string>h=g;if(f&1)reverse(h.begin(),h.end());if(f&2)for(auto&s:h)reverse(s.begin(),s.end());ans=max(ans,solve(h,k));}
 printf("%d\n",ans);}}

