using namespace std;
typedef long long ll;const ll INF=4e18;
int n,m;vector<int>g,par;vector<ll>w; // weighted DSU: an informed v points along g; w = distance to the parent
pair<int,ll> find(int v){vector<int>path;while(par[v]!=v){path.push_back(v);v=par[v];} // v = root (uninformed or sentinel)
 ll acc=0;for(int i=path.size()-1;i>=0;i--){int u=path[i];acc=min(INF,acc+w[u]);w[u]=acc;par[u]=v;}
 return {v,path.empty()?0:w[path[0]]};}
int main(){scanf("%d %d",&n,&m);g.resize(n+2);for(int i=1;i<=n;i++)scanf("%d",&g[i]);vector<ll>v(m),b(m);
 for(auto&x:v)scanf("%lld",&x);for(auto&x:b)scanf("%lld",&x);
 par.resize(n+2);w.assign(n+2,0);for(int i=0;i<=n+1;i++)par[i]=i;int SENT=n+1;ll res=0;
 for(int i=0;i<m;i++){int cur=(v[i]+res-1)%n+1;ll rem=b[i];res=0; // a_i = (v_i + res_{i-1} - 1) mod n + 1
  while(rem>0){auto[r,d]=find(cur);if(r==SENT||d>=rem)break;res++;rem-=d+1;
   auto[r2,d2]=find(g[r]);if(r2==r){par[r]=SENT;w[r]=INF;}else{par[r]=g[r];w[r]=1;} // closing a fully informed cycle -> sentinel
   cur=g[r];}
  printf("%lld\n",res);}}

#include <bits/stdc++.h>
using namespace std;
int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);vector<int>a(n+1),fst(n+1,0),R(n+1,0);
 for(int i=1;i<=n;i++){scanf("%d",&a[i]);if(!fst[a[i]])fst[a[i]]=i;else R[fst[a[i]]]=i;} // R[l] = the matching right end
 vector<int>bit(n+2,0); // max over r' > r, indexed by reversed r
 auto upd=[&](int r,int v){for(int i=n+1-r;i<=n;i+=i&-i)bit[i]=max(bit[i],v);};
 auto qry=[&](int r){int s=0;for(int i=n-r;i>0;i-=i&-i)s=max(s,bit[i]);return s;}; // over r' > r
 int ans=1;
 for(int l=1;l<=n;l++)if(R[l]){int r=R[l];int f=qry(r)+1;ans=max(ans,2*f+(r-l>1?1:0));upd(r,f);} // l ascending: earlier pairs have smaller l
 printf("%d\n",ans);}}
